import json

import pytest

from logic_agent.errors import ValidationError
from logic_agent.models import Limits
from logic_agent.service import LogicAgentService


def write_dsview_csv(path, channels=("0",), rate=10_000_000, seconds=0.01, frequency_hz=1_000):
    period = rate / frequency_hz
    lines = [
        "; CSV, generated by DSView",
        f"; Sample rate: {rate}",
        "Time(s)," + ",".join(channels),
    ]
    for index in range(round(rate * seconds)):
        high = (index % period) < period / 2
        lines.append(f"{index / rate:.9f}," + ",".join("1" if high else "0" for _ in channels))
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")


@pytest.fixture()
def service(tmp_path):
    svc = LogicAgentService(data_dir=tmp_path / "data")
    svc.default_backend = "mock"
    return svc


def test_capture_persists_metadata_not_arrays(service):
    result = service.capture(
        {"channels": ["D0", "D1"], "sample_rate_hz": 1_000_000, "duration_s": 0.005}
    )
    assert result["ok"] is True
    assert result["sample_count"] == 5_000
    assert {item["id"] for item in result["channels"]} == {"D0", "D1"}
    assert "samples" not in json.dumps(result)
    manifest = service.store.manifest(result["capture_id"])
    assert manifest["schema_version"] == "1.0"
    assert len(manifest["channels"]) == 2
    for channel in manifest["channels"]:
        assert len(channel["sha256"]) == 64


def test_analyze_window_returns_bounded_edges(service):
    captured = service.capture(
        {"channels": ["D1"], "sample_rate_hz": 1_000_000, "duration_s": 0.01}
    )
    report = service.analyze_window(
        {"capture_id": captured["capture_id"], "channel": "D1", "max_edges": 3}
    )
    assert len(report["edges"]) == 3
    assert report["edges_truncated"] is True
    assert report["total_edges"] > 3


def test_decode_mock_uart(service):
    captured = service.capture(
        {"channels": ["D0"], "sample_rate_hz": 1_000_000, "duration_s": 0.02}
    )
    decoded = service.decode_uart({"capture_id": captured["capture_id"], "channel": "D0"})
    assert decoded["byte_count"] > 0
    assert any("PING" in group["text"] for group in decoded["groups"])


def test_limits_reject_oversized_capture(tmp_path):
    svc = LogicAgentService(
        data_dir=tmp_path,
        limits=Limits(max_total_samples=1_000),
    )
    svc.default_backend = "mock"
    with pytest.raises(ValidationError):
        svc.capture({"channels": ["D0"], "sample_rate_hz": 1_000_000, "duration_s": 0.01})


def test_invalid_channel_has_actionable_details(service):
    with pytest.raises(ValidationError):
        service.capture({"channels": ["NOPE"], "sample_rate_hz": 1_000_000, "duration_s": 0.001})


def test_resource_preview(service):
    captured = service.capture(
        {"channels": ["D0"], "sample_rate_hz": 1_000_000, "duration_s": 0.005}
    )
    text, mime = service.read_resource(captured["capture_id"])
    assert mime == "application/json"
    assert json.loads(text)["id"] == captured["capture_id"]


def test_import_dsview_csv_and_measure_period(service, tmp_path):
    csv_path = tmp_path / "dsview.csv"
    write_dsview_csv(csv_path)
    imported = service.import_csv({"path": str(csv_path), "channels": ["0"], "label": "1 kHz probe"})
    assert imported["ok"] is True
    assert imported["sample_rate_hz"] == 10_000_000
    report = service.measure_period({"capture_id": imported["capture_id"], "channel": "0"})
    assert report["periodic"] is True
    assert abs(report["frequency_hz"] - 1_000) < 2
    assert abs(report["duty_cycle"] - 0.5) < 0.02


def test_import_csv_rejects_missing_channel(service, tmp_path):
    csv_path = tmp_path / "dsview.csv"
    write_dsview_csv(csv_path)
    with pytest.raises(ValidationError):
        service.import_csv({"path": str(csv_path), "channels": ["9"]})

